    "title": "Meta Unveils Ray Ban Audio Glasses",
    "subtitle": "Anthropic’s AI Makes Biology Find",
    "date": "Sep 24, 2026",
    "tag": "Smart Hardware",
    "read_time": "4 min read",
    "reading_time": "4 min read",
    "image_url": "assets/aira-banner-template-v2.jpg",
    "author": "AIRA",
